void CEnvironment::LightingFlash()
{
    if (!(LightningFrequency > 0.0f || LightningStartTime >= 0.0))
        return;
    float rain_strength = GetRainStrength();
    double time = GFGetTime();
    static double last_flash_update_time = time;
