void CAIStateGroup_TavernServer::Update()
{
    CTCVillageMember* village_member;
    GetCreature().GetTC(&village_member);
    village_member->GetPVillage();
    for (;;) {
        if (ServingActionPointIndex == -1 && !GetServingPoint())
            break;
        if (!IsCarryingJug()) {
            if (!GetJug())
                break;
            if (!WalkToBar())
                break;
            if (!PickUpJug())
                break;
