        CTCTavernJug* jug;
        if (!IS_THING_ALIVE(PJug) || !PJug->GetTC(&jug))
            break;
        while (jug->Fullness > 0) {
            if (ServingActionPointIndex == -1 && !GetServingPoint())
                break;
